// ConfigFromJSON creates Config from JSON bytes.
// Uses standard encoding/json and custom enum parsers for external JSON compatibility.
func ConfigFromJSON(data []byte) (*Config, error) {
	// Unmarshal into helper struct with string enums
	var raw configJSON
	if err := json.Unmarshal(data, &raw); err != nil {
		// Fall back to protojson which handles proto3 JSON conventions
		// (string-encoded int64/uint64, standard enum names, etc.)
		v := &Config{}
		if pErr := protojson.Unmarshal(data, v); pErr != nil {
			return nil, err
		}
		return v, nil
	}
	// Build result with parsed enums
	result := &Config{}
	// Parse enum field: Mode
	if raw.Mode != "" {
		if parsed, err := ParseOperatorMode(raw.Mode); err == nil {
			result.Mode = parsed
		}
	}
	result.Fqdn = raw.Fqdn
	result.Port = raw.Port
	result.Namespace = raw.Namespace
	// Parse message field: Topology
	if len(raw.Topology) > 0 {
		parsed, err := TopologyFromJSON(raw.Topology)
		if err == nil {
			result.Topology = parsed
		}
	}
	// Parse message field: Tls
	if len(raw.Tls) > 0 {
		parsed, err := TLSConfigFromJSON(raw.Tls)
		if err == nil {
			result.Tls = parsed
		}
	}
	// Parse message field: Pki
	if len(raw.Pki) > 0 {
		parsed, err := PKIFromJSON(raw.Pki)
		if err == nil {
			result.Pki = parsed
		}
	}
	// Parse message field: OptionalServices
	if len(raw.OptionalServices) > 0 {
		parsed, err := OptionalServicesFromJSON(raw.OptionalServices)
		if err == nil {
			result.OptionalServices = parsed
		}
	}
	result.OutputDir = raw.OutputDir
	result.WebRoot = raw.WebRoot
	result.Patch = raw.Patch
	result.Dev = raw.Dev
	result.GitlabRegistryToken = raw.GitlabRegistryToken
	result.SpiffePrefix = raw.SpiffePrefix
	// Parse repeated message field: RootCredPairs
	if len(raw.RootCredPairs) > 0 {
		result.RootCredPairs = make([]*credentials.CredPair, 0, len(raw.RootCredPairs))
		for _, itemJSON := range raw.RootCredPairs {
			if len(itemJSON) > 0 {
				parsed, err := credentials.CredPairFromJSON(itemJSON)
				if err == nil {
					result.RootCredPairs = append(result.RootCredPairs, parsed)
				}
			}
		}
	}
	// Parse message field: ClusterOauth
	if len(raw.ClusterOauth) > 0 {
		parsed, err := oauth.ClusterOAuthConfigFromJSON(raw.ClusterOauth)
		if err == nil {
			result.ClusterOauth = parsed
		}
	}
	// Parse message field: Kmaker
	if len(raw.Kmaker) > 0 {
		parsed, err := kmaker.ConfigFromJSON(raw.Kmaker)
		if err == nil {
			result.Kmaker = parsed
		}
	}
	result.LlmCredential = raw.LlmCredential
	result.LlmCredentialServices = raw.LlmCredentialServices
	result.TraceId = raw.TraceId
	result.Noop = raw.Noop
	return result, nil
}

// ConfigToYAML converts Config to YAML bytes.
