// ============================================================
// Merge: Config
// ============================================================
// MergeConfig fills zero-valued fields in dst from src.
func MergeConfig(dst, src *Config) {
	if dst.Mode == 0 {
		dst.Mode = src.Mode
	}
	if dst.Fqdn == "" {
		dst.Fqdn = src.Fqdn
	}
	if dst.Port == 0 {
		dst.Port = src.Port
	}
	if dst.Namespace == "" {
		dst.Namespace = src.Namespace
	}
	if dst.Topology == nil {
		dst.Topology = src.Topology
	} else if src.Topology != nil {
		MergeTopology(dst.Topology, src.Topology)
	}
	if dst.Tls == nil {
		dst.Tls = src.Tls
	} else if src.Tls != nil {
		MergeTLSConfig(dst.Tls, src.Tls)
	}
	if dst.Pki == nil {
		dst.Pki = src.Pki
	} else if src.Pki != nil {
		MergePKI(dst.Pki, src.Pki)
	}
	if dst.OptionalServices == nil {
		dst.OptionalServices = src.OptionalServices
	} else if src.OptionalServices != nil {
		MergeOptionalServices(dst.OptionalServices, src.OptionalServices)
	}
	if dst.OutputDir == "" {
		dst.OutputDir = src.OutputDir
	}
	if dst.WebRoot == "" {
		dst.WebRoot = src.WebRoot
	}
	if dst.Patch == 0 {
		dst.Patch = src.Patch
	}
	if !dst.Dev {
		dst.Dev = src.Dev
	}
	if dst.GitlabRegistryToken == "" {
		dst.GitlabRegistryToken = src.GitlabRegistryToken
	}
	if dst.SpiffePrefix == "" {
		dst.SpiffePrefix = src.SpiffePrefix
	}
	if len(dst.RootCredPairs) == 0 {
		dst.RootCredPairs = src.RootCredPairs
	}
	if dst.ClusterOauth == nil {
		dst.ClusterOauth = src.ClusterOauth
	}
	if dst.Kmaker == nil {
		dst.Kmaker = src.Kmaker
	}
	if dst.LlmCredential == "" {
		dst.LlmCredential = src.LlmCredential
	}
	if len(dst.LlmCredentialServices) == 0 {
		dst.LlmCredentialServices = src.LlmCredentialServices
	}
	if dst.TraceId == "" {
		dst.TraceId = src.TraceId
	}
	if !dst.Noop {
		dst.Noop = src.Noop
	}
}

